use crate::wasi::clocks::wall_clock;

struct Node;

/// Last day representable as a 4-digit year: 9999-12-31, in days since 1970-01-01.
const MAX_DAYS: u64 = 2_932_896;

/// Convert days since the Unix epoch to (year, month, day) in the proleptic
/// Gregorian calendar (Howard Hinnant's civil_from_days).
fn civil_from_days(days: u64) -> (u64, u64, u64) {
    let z = days.min(MAX_DAYS) + 719_468;
    let era = z / 146_097;
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365;
    let mut y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    if m <= 2 {
        y += 1;
    }
    (y, m, d)
}

impl Guest for Node {
    fn run(_tick: Tick) -> RunInfo {
        let now = wall_clock::now();
        let seconds = now.seconds;

        let (y, m, d) = civil_from_days(seconds / 86_400);
        // Year is clamped to <= 9999 and >= 1970, so this is always 10 chars.
        let date = format!("{:04}-{:02}-{:02}", y, m, d);

        RunInfo {
            date,
            started: seconds,
        }
    }
}

export!(Node);
